import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"What is caldav-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788611498000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-caldav-mcp" tabindex="-1">What is caldav-mcp? <a class="header-anchor" href="#what-is-caldav-mcp" aria-label="Permalink to “What is caldav-mcp?”">​</a></h1><p>MCP server for CalDAV calendars: events, tasks and journal entries</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>CalDAV is the open standard almost every calendar that is not Google or Exchange speaks: Nextcloud, Radicale, Baikal, SOGo, Fastmail, mailbox.org, iCloud. One server therefore reaches all of them, and reaches them directly — there is no vendor API in between, and nothing about your calendar leaves the machine except to the server you configured.</p><p>The awkward parts of a calendar are the parts a general-purpose HTTP tool cannot do for you. A recurring meeting is stored as one rule and a handful of exceptions, so &quot;what is on next Tuesday&quot; is a computation rather than a lookup. A timestamp means nothing without the zone it was written in, and the zone is frequently referenced and not included. Writing anything back replaces the whole entry, so a careless edit removes the reminders and the attendees of an appointment without saying so.</p><p>caldav-mcp does those three things properly and gets out of the way:</p><ul><li><strong>Recurring entries are expanded here</strong>, into occurrences with ids of their own, so one instance can be changed without touching the series. Asking the calendar server to expand them is possible and unreliable — support is uneven and its absence is silent — so this server does it and behaves the same everywhere.</li><li><strong>Times carry their zone.</strong> Every timestamp comes back as an instant with an offset, the IANA zone the entry was written in, and a flag for whole-day entries. A daily 09:00 meeting stays at 09:00 across a daylight-saving change, which is not what naive date handling does.</li><li><strong>Writing reads first.</strong> Every change is applied to the entry as stored, so the properties this server does not model — attendees, attachments, the reminders it cannot write, anything a vendor added — survive because they are never touched. The write carries the entry&#39;s ETag, so a change made elsewhere in the meantime is reported rather than overwritten.</li></ul><p>Calendar content is also somebody else&#39;s writing. On a server with scheduling enabled, anyone who knows your address can put an entry in your calendar without you accepting it, so everything read out of one is marked as untrusted data and fenced before it reaches the model. See <a href="/guide/security">Security</a>.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Not a scheduling client.</strong> It can answer an invitation with your own participation status, and that is all: it cannot add or remove attendees, and therefore cannot invite or cancel on anybody.</li><li><strong>Not a calendar manager.</strong> It lists calendars and never creates or deletes one. Deleting a collection removes everything in it at once, which is the largest single destruction available in this protocol, for an operation people perform once a year in a web interface.</li><li><strong>Not a file reader.</strong> An attachment on an entry is reported as metadata — name, type, size, and the URL if it has one — and never fetched or decoded.</li><li><strong>Not a CardDAV client.</strong> Contacts are a different specification with a different data format, and belong in a different server.</li></ul><p>See <a href="https://github.com/ni-c/caldav-mcp#not-exposed-on-purpose" target="_blank" rel="noreferrer">Not exposed, on purpose</a> for the full list and the reasoning behind each.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};